    --color-bgInverse: rgb(255, 255, 255);
    --color-bgOverlay: rgba(0, 0, 0, 0.502);
    --color-bgElevation1: rgb(26, 26, 26);
    --color-bgElevation2: rgb(38, 38, 38);
    --color-bgPrimary: rgb(65, 81, 96);
    --color-bgPrimaryWash: rgb(1, 23, 43);
    --color-bgSecondary: rgb(26, 26, 26);
    --color-bgTertiary: rgb(51, 51, 51);
    --color-bgSecondaryWash: rgb(20, 21, 25);
    --color-bgNegative: rgb(214, 8, 8);
    --color-bgNegativeWash: rgba(247, 50, 50, 0.149);
    --color-bgPositive: rgb(0, 196, 91);
    --color-bgPositiveWash: rgba(0, 231, 107, 0.149);
    --color-bgWarning: rgb(242, 100, 20);
    --color-bgWarningWash: rgba(242, 100, 20, 0.149);
    --color-bgInfoWash: rgba(24, 23, 231, 0.251);

    --color-bgLine: rgba(255, 255, 255, 0.18);
    --color-bgLineHeavy: rgba(138, 145, 158, 0.66);
    --color-bgLineInverse: rgb(0, 0, 0);
    --color-bgLinePrimary: rgb(128, 127, 242);
    --color-bgLinePrimarySubtle: rgb(5, 59, 177);
    --color-fgDisabled: rgba(255, 255, 255, 0.451);
    --color-fgInverseDisabled: rgba(0, 0, 0, 0.451);
    --color-fgLink: rgb(140, 139, 243);
    --color-fgLinkHover: rgb(209, 209, 250);
    --color-bgButtonPrimaryHover: rgb(90, 104, 117);
    --color-bgButtonPrimaryActive: rgb(90, 104, 117);
    --color-bgButtonSecondary: rgba(255, 255, 255, 0.122);
    --color-bgButtonSecondaryHover: rgba(255, 255, 255, 0.149);
    --color-bgButtonSecondaryActive: rgba(255, 255, 255, 0.149);
    --color-bgButtonBrand: rgb(217, 225, 7);
    --color-bgButtonInverse: rgb(26, 26, 26);
    --color-bgButtonInverseHover: rgb(38, 38, 38);
    --color-bgButtonInverseActive: rgb(51, 51, 51);
    --color-bgButtonInverseDisabled: rgba(1, 23, 43, 0.102);
    --color-bgButtonTertiaryInverseHover: rgba(1, 23, 43, 0.122);
    --color-bgButtonTertiaryInverseActive: rgba(1, 23, 43, 0.149);
    --color-bgLineFocusInverse: rgb(0, 0, 0);
    --color-bgButtonDisabled: rgba(255, 255, 255, 0.102);
    --color-bgField: rgba(255, 255, 255, 0.122);
    --color-bgFieldHover: rgba(255, 255, 255, 0.149);
    --color-bgFieldDisabled: rgba(255, 255, 255, 0.031);
    --color-bgLineStrong: rgb(255, 255, 255);
    --color-bgLineDisabled: rgba(255, 255, 255, 0.451);
    --color-bgLineNegative: rgb(243, 9, 9);
    --color-fgPlaceholder: rgba(255, 255, 255, 0.651);
    --color-fgHelper: rgba(255, 255, 255, 0.651);
    --color-fgIcon: rgb(255, 255, 255);
    --color-fgIconDisabled: rgba(255, 255, 255, 0.451);
    --color-bgToggleOn: rgb(255, 255, 255);
    --color-fgIconInverse: rgba(0, 0, 0, 0.851);
    --color-bgElevation1Hover: rgba(255, 255, 255, 0.078);
    --color-bgElevation1Active: rgba(255, 255, 255, 0.122);
    --color-bgElevation1Selected: rgba(255, 255, 255, 0.122);
    --color-bgTagNeutral: rgba(166, 191, 204, 0.122);
    --color-bgTagNeutralHover: rgba(166, 191, 204, 0.18);
    --color-bgTagNeutralDisabled: rgba(166, 191, 204, 0.122);
    --color-fgTagNeutral: rgb(192, 197, 202);
    --color-bgLineTagNeutral: rgba(166, 191, 204, 0.251);
    --color-bgElevation3: rgb(64, 64, 64);
    --color-bgInfo: rgb(140, 139, 243);
    --color-fgInteractive: rgb(140, 139, 243);
    --color-fgIconMuted: rgba(255, 255, 255, 0.651);
    --color-bgTagPositive: rgba(0, 231, 107, 0.122);
    --color-fgTagPositive: rgb(0, 208, 96);
    --color-bgTagWarning: rgba(242, 100, 20, 0.122);
    --color-fgTagWarning: rgb(245, 139, 79);
    --color-bgTagNegative: rgba(247, 50, 50, 0.122);
    --color-fgTagNegative: rgb(249, 112, 112);
    --color-bgHighlight: rgba(24, 23, 231, 0.251);

    --color-transparent: rgba(255, 255, 255, 0);
  }
}

/* --- Colors (dark) — manual override via data-theme="dark" --- */
:root[data-theme='dark'] {
  --color-fg: rgb(255, 255, 255);
